WITH cleaned AS (SELECT *, LENGTH(location) AS location_length, CONCAT(location, '/', dept_name) AS location_dept_name, COALESCE(location, 'N/A') AS location_filled FROM departments WHERE location NOT IN ('New York', 'London')) SELECT dept_name, PERCENTILE_APPROX(location_length, 0.5) AS location_length_p50, COUNT_IF(location = 'Berlin') AS berlin_events, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, COUNT(DISTINCT dept_name) AS distinct_dept_names, MAX(location_length) AS max_location_length FROM cleaned GROUP BY dept_name
